    return new Iterator<T>() {
      private int cursor;
      public boolean hasNext() {
        return cursor < items.size();
      }
      public T next() {
        if (!hasNext())
          throw new NoSuchElementException();
        return Get(cursor++);
      }
    };
  }
}

